CREATE TABLE Institution (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, Country TEXT);
CREATE TABLE Department (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, InstitutionId INTEGER REFERENCES Institution (Id), HeadId INTEGER);
CREATE TABLE Researcher (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, Email TEXT, InstitutionId INTEGER REFERENCES Institution (Id), AdvisorId INTEGER REFERENCES Researcher (Id), HIndex INTEGER, Salary REAL, Active INTEGER);
CREATE TABLE Conference (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, Rank TEXT);
CREATE TABLE Paper (Id INTEGER PRIMARY KEY, Title TEXT NOT NULL, Year INTEGER, Citations INTEGER, ConferenceId INTEGER REFERENCES Conference (Id));
CREATE TABLE PaperAuthor (PaperId INTEGER REFERENCES Paper (Id), ResearcherId INTEGER REFERENCES Researcher (Id), Position INTEGER, PRIMARY KEY (PaperId, ResearcherId));
CREATE TABLE "Grant" (Id INTEGER PRIMARY KEY, Title TEXT NOT NULL, Amount REAL, ResearcherId INTEGER REFERENCES Researcher (Id), StartYear INTEGER);
